import React from "react";
import axios from "axios";
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import Success from "../../success";
import Form from 'react-bootstrap/Form';
import Button from 'react-bootstrap/esm/Button'
import Logo from '../../assets/images/Logo.jpeg'

const Signup = () => {
  const [signupData, setSignupData] = useState({
    name: "",
    username: "",
    email: "",
    password: "",
  });
    const [signUpSuccess, setSignUpSuccess] = useState(false);
  const navigate = useNavigate();

  const addStudent = () => {
    if (!signupData.name || !signupData.username || !signupData.email || !signupData.password) {
      alert("Please fill in all fields");
      return;
    }
    if (signupData.password.length < 6) {
      alert("Password must be at least 6 characters long");
      return;
    }
    axios
      .post("http://localhost:5000/students/", {
        fullName: signupData.name,
        username: signupData.username,
        email: signupData.email,
        password: signupData.password,
      })
      .then((response) => {
        console.log(response.data);
        // navigate("/dashboard");
            setSignUpSuccess(true);
      })
      .catch((error) => {
        alert("Error adding student:", error);
      });
  };

  if (signUpSuccess) {
    return <Success name={signupData.name} type="Signed up" />;
  }

  return (
    <div className='d-flex justify-content-center align-items-center'>
    <img src={Logo} alt="Logo" className='mt-5 d-block border rounded' style={{width: "37%"}} />
     <div className='m-5 pt-3' style={{width: "450px"}}>
      <h3 className="text-center mt-3">Signup</h3>
      <Form>
            <Form.Group className="mb-3" controlId="formGroupEmail">
              <Form.Label>Name</Form.Label>
              <Form.Control type="text" placeholder="Enter name" value={signupData.name} onChange={(e) => setSignupData({ ...signupData, name: e.target.value })} />
            </Form.Group>
            <Form.Group className="mb-3" controlId="formGroupUsername">
              <Form.Label>Username</Form.Label>
              <Form.Control type="text" placeholder="Enter username" value={signupData.username} onChange={(e) => setSignupData({ ...signupData, username: e.target.value })} />
            </Form.Group>
            <Form.Group className="mb-3" controlId="formGroupEmail">
              <Form.Label>Email</Form.Label>
              <Form.Control type="email" placeholder="Enter email" value={signupData.email} onChange={(e) => setSignupData({ ...signupData, email: e.target.value })} />
            </Form.Group>
            <Form.Group className="mb-3" controlId="formGroupPassword">
              <Form.Label>Password</Form.Label>
              <Form.Control type="password" placeholder="Enter password" value={signupData.password} onChange={(e) => setSignupData({ ...signupData, password: e.target.value })} />
            </Form.Group>
                  <div className='d-flex'>
                    <p className='mt-3'>Already have an account? </p>
                  <Button variant="link" onClick={() => navigate("/login")}>Login</Button>
                  </div>
                  <div className='d-flex justify-content-between'>
                  <Button variant="dark" onClick={() => navigate("/")}>Home</Button>
                  <Button variant="primary" onClick={addStudent}>Sign Up</Button>
                  </div>
          </Form>
    </div>
    </div>
  );
};

export default Signup;
